using namespace tigersheets;
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
Json fixture(){return Json::parse(R"({"revision":0,"sheets":[{"id":"s","name":"Data","cells":[{"row":1,"col":1,"input":"'00123","style":{"bold":true,"note":"Keep this note","fill":"#ffffff"}},{"row":1,"col":2,"input":"=1+2","style":{"italic":true}},{"row":2,"col":1,"input":"TRUE"},{"row":2,"col":2,"input":"#N/A"},{"row":3,"col":1,"input":"Outside"}]}]})");}
void select(QTableView& view,WorksheetModel& model,int top=0,int left=0,int bottom=1,int right=1){view.setCurrentIndex(model.index(top,left));view.selectionModel()->select(QItemSelection(model.index(top,left),model.index(bottom,right)),QItemSelectionModel::ClearAndSelect);}
void directFormatting(){WorkbookSession session(fixture());WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model);int changes=0;model.onChanged=[&]{++changes;};
 const Json style={{"numberFormat","0.00"},{"alignment","center"},{"fontFamily","DejaVu Sans"},{"fontSize",13},{"color","#123456"}};
 require(formatWorksheetCells(nullptr,model,view,{{"style",style}}),"direct cell formatting succeeds");
 for(int row=0;row<2;++row)for(int col=0;col<2;++col){const auto actual=model.cellStyle(row,col);for(const auto& [key,value]:style.items())require(actual.at(key)==value,"the complete selected rectangle receives formatting");}
 require(model.raw(0,0)=="'00123"&&model.raw(0,1)=="=1+2"&&model.raw(1,0)=="TRUE"&&model.raw(1,1)=="#N/A"&&model.cellStyle(0,0).at("note")=="Keep this note"&&model.cellStyle(0,0).at("bold")==true&&model.cellStyle(0,1).at("italic")==true,"formatting preserves typed inputs, formulas, notes and existing styles");
 require(model.cellStyle(2,0).empty()&&changes==1&&session.snapshotView().at("revision")==1,"formatting affects only the selection in one transaction");
 require(session.undo(),"formatting supports one undo");model.refresh();require(session.snapshotView().at("sheets")==fixture().at("sheets"),"one undo restores all original formatting and values");
}
void clearFormats(){auto source=fixture();source["sheets"][0]["cells"][0]["style"]["ooxmlStyleId"]=7;source["sheets"][0]["cells"][0]["style"]["wrap"]=true;WorkbookSession session(source);WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model);int changes=0;model.onChanged=[&]{++changes;};
 require(clearWorksheetFormats(model,view),"clear formats succeeds");require(model.cellStyle(0,0)==Json({{"note","Keep this note"}})&&model.cellStyle(0,1).empty(),"clear formats removes every visual style including imported style identity but retains the note");
 require(model.raw(0,0)=="'00123"&&model.raw(0,1)=="=1+2"&&model.raw(1,0)=="TRUE"&&model.raw(1,1)=="#N/A"&&changes==1,"clear formats preserves values and formulas in one observable transaction");
 require(session.undo(),"clear formats supports undo");model.refresh();require(session.snapshotView().at("sheets")==source.at("sheets"),"one undo restores imported and ordinary styles exactly");
}
void nativeDialog(){WorkbookSession session(fixture());WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model);QString failure;bool opened=false;
 QTimer::singleShot(0,[&]{auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget());if(!dialog){failure="Format Cells did not open a native modal dialog";return;}try{opened=true;require(dialog->objectName()=="formatCells.dialog"&&dialog->windowTitle()=="Format Cells","dialog identity and title match Format Cells");auto* tabs=dialog->findChild<QTabWidget*>("formatCells.tabs");require(tabs&&tabs->count()==4&&tabs->tabText(0)=="Number"&&tabs->tabText(1)=="Alignment"&&tabs->tabText(2)=="Font"&&tabs->tabText(3)=="Fill","all four formatting tabs are available");
 auto* number=dialog->findChild<QComboBox*>("formatCells.numberFormat");auto* alignment=dialog->findChild<QComboBox*>("formatCells.alignment");auto* bold=dialog->findChild<QCheckBox*>("formatCells.bold");auto* fill=dialog->findChild<QLineEdit*>("formatCells.fill");auto* size=dialog->findChild<QSpinBox*>("formatCells.fontSize");auto* buttons=dialog->findChild<QDialogButtonBox*>("formatCells.buttons");require(number&&alignment&&bold&&fill&&size&&buttons,"native formatting controls are discoverable");require(!number->accessibleName().isEmpty()&&!alignment->accessibleName().isEmpty()&&!bold->accessibleName().isEmpty()&&bold->isChecked()&&fill->text()=="#ffffff"&&number->currentText()=="General","controls have accessible names and current cell defaults");
 number->setEditText("$#,##0.00");alignment->setCurrentIndex(alignment->findData("right"));size->setValue(14);tabs->setCurrentIndex(3);fill->setFocus();fill->selectAll();QTest::keyClicks(fill,"#ffeecc");QTest::mouseClick(buttons->button(QDialogButtonBox::Ok),Qt::LeftButton);
 }catch(const std::exception& error){failure=QString::fromUtf8(error.what());dialog->reject();}});
 require(formatWorksheetCells(nullptr,model,view),"accepting Format Cells applies the draft");require(failure.isEmpty(),failure.toUtf8().constData());require(opened,"a real dialog was shown");
 require(model.cellStyle(0,0).at("numberFormat")=="$#,##0.00"&&model.cellStyle(1,1).at("alignment")=="right"&&model.cellStyle(1,1).at("fontSize")==14&&model.cellStyle(1,1).at("fill")=="#ffeecc","accepted controls format every selected cell");
 require(!model.cellStyle(0,1).contains("bold")&&model.cellStyle(0,1).at("italic")==true,"unmodified controls preserve different existing styles across the selection");require(session.undo(),"dialog formatting is one undo");model.refresh();require(session.snapshotView().at("sheets")==fixture().at("sheets"),"undo restores dialog changes together");
 const auto before=session.snapshot();QTimer::singleShot(0,[&]{auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget());if(!dialog){failure="Cancel dialog missing";return;}dialog->findChild<QComboBox*>("formatCells.numberFormat")->setEditText("0%");QTest::keyClick(dialog,Qt::Key_Escape);});require(!formatWorksheetCells(nullptr,model,view)&&session.snapshot()==before,"Escape discards all formatting drafts without history");
}
void validation(){WorkbookSession session(fixture());WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model);const auto before=session.snapshot();
 for(const auto& style:Json::array({Json{{"unsupported",true}},Json{{"note","replace note"}},Json{{"alignment","diagonal"}},Json{{"color","not-a-color"}},Json{{"fill",7}},Json{{"fontSize",401}},Json{{"fontFamily",""}},Json{{"bold","yes"}}})){bool rejected=false;try{formatWorksheetCells(nullptr,model,view,{{"style",style}});}catch(const std::exception&){rejected=true;}require(rejected&&session.snapshot()==before&&!session.canUndo(),"unsupported or malformed style properties refuse atomically");}
 view.selectionModel()->select(QItemSelection(model.index(3,0),model.index(3,0)),QItemSelectionModel::Select);bool rejected=false;try{clearWorksheetFormats(model,view);}catch(const std::exception&){rejected=true;}require(rejected&&session.snapshot()==before,"discontinuous selections refuse without formatting gaps");
 select(view,model,0,0,100000,0);rejected=false;try{formatWorksheetCells(nullptr,model,view,{{"style",{{"bold",true}}}});}catch(const std::exception&){rejected=true;}require(rejected&&session.snapshot()==before,"formatting above the bounded selection limit refuses before allocation or mutation");
}
void noChanges(){WorkbookSession session(fixture());WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model);const auto before=session.snapshot();
 require(formatWorksheetCells(nullptr,model,view,{{"style",Json::object()}})&&session.snapshot()==before&&!session.canUndo(),"an empty formatting change creates no blank styles or undo entry");
 QTimer::singleShot(0,[]{if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget()))dialog->accept();});require(formatWorksheetCells(nullptr,model,view)&&session.snapshot()==before&&!session.canUndo(),"accepting unchanged dialog settings preserves mixed formatting and creates no history");
}
void clearUnformatted(){WorkbookSession session;WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model);const auto before=session.snapshot();require(clearWorksheetFormats(model,view)&&session.snapshot()==before&&!session.canUndo(),"clearing an unformatted range does not allocate blank cells or create history");}
void clearColors(){WorkbookSession session(fixture());WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model);
 require(formatWorksheetCells(nullptr,model,view,{{"style",{{"fill",""},{"color",""}}}}),"No Fill and Automatic font color accept explicit reset values");require(!model.data(model.index(0,0),Qt::BackgroundRole).isValid()&&!model.data(model.index(0,0),Qt::ForegroundRole).isValid(),"cleared colors use default grid brushes rather than invalid QColor brushes");
 require(model.cellStyle(0,0).at("fill")==""&&model.cellStyle(0,0).at("color")==""&&model.cellStyle(0,0).at("bold")==true&&model.cellStyle(0,0).at("note")=="Keep this note"&&model.raw(0,0)=="'00123","color reset sentinels preserve unrelated styles, notes and cell values");require(session.undo(),"color resets are one undo");model.refresh();require(session.snapshotView().at("sheets")==fixture().at("sheets"),"one undo restores color settings exactly");
}
void explicitLeft(){WorkbookSession session(Json::parse(R"({"revision":0,"sheets":[{"id":"s","name":"Numbers","cells":[{"row":1,"col":1,"input":"42"},{"row":1,"col":2,"input":"=40+2"}]}]})"));WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model,0,0,0,1);
 require(formatWorksheetCells(nullptr,model,view,{{"style",{{"alignment","left"}}}}),"Format Cells accepts explicit Left alignment");model.setCalculated({{"revision",1},{"status","ok"},{"values",Json::array({{{"sheet","s"},{"row",1},{"col",2},{"type","number"},{"value",42}}})}});
 for(int col=0;col<2;++col)require((model.data(model.index(0,col),Qt::TextAlignmentRole).toInt()&Qt::AlignHorizontal_Mask)==Qt::AlignLeft,"explicit Left aligns both numeric literals and calculated numeric formulas to the left");
}
bool withDialog(WorksheetModel& model,QTableView& view,const std::function<void(QDialog*)>& interact,const Json& arguments=Json::object()){QString failure;QTimer::singleShot(0,[&]{auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget());if(!dialog){failure="native Format Cells dialog is missing";return;}try{interact(dialog);}catch(const std::exception& error){failure=QString::fromUtf8(error.what());dialog->reject();}});const bool accepted=formatWorksheetCells(nullptr,model,view,arguments);require(failure.isEmpty(),failure.toUtf8().constData());return accepted;}
void nativeNumberOptions(){
 auto book=fixture();book["sheets"][0]["cells"][0]["input"]="-1234.567";WorkbookSession session(book);WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model,0,0,0,0);const auto before=session.snapshot();
 require(withDialog(model,view,[](QDialog* dialog){auto* category=dialog->findChild<QComboBox*>("formatCells.category");auto* decimals=dialog->findChild<QSpinBox*>("formatCells.decimalPlaces");auto* grouping=dialog->findChild<QCheckBox*>("formatCells.thousandsSeparator");auto* negatives=dialog->findChild<QComboBox*>("formatCells.negativeStyle");auto* sample=dialog->findChild<QLabel*>("formatCells.sample");require(category&&decimals&&grouping&&negatives&&sample,"Number tab exposes category, decimal places, grouping, negative style and a live sample");
  category->setCurrentIndex(category->findData("number"));decimals->setValue(2);grouping->setChecked(true);negatives->setCurrentIndex(negatives->findData("parentheses"));require(sample->text()=="(1,234.57)","Number sample updates decimal rounding, grouping and parentheses without changing the value");dialog->accept();}),"accept native Number options");
 require(model.cellStyle(0,0).at("numberFormat")=="#,##0.00;(#,##0.00)"&&model.data(model.index(0,0)).toString()=="(1,234.57)","Number options generate an applied Excel number format");require(model.raw(0,0)=="-1234.567"&&model.cellStyle(0,0).at("bold")==true&&model.cellStyle(0,0).at("note")=="Keep this note","display rounding preserves the numeric input and unrelated styles");require(session.undo(),"native Number options are one undo");model.refresh();require(session.snapshotView().at("sheets")==before.at("sheets"),"one undo restores Number format and existing styles exactly");
}
void nativeCurrencyOptions(){
 auto book=fixture();book["sheets"][0]["cells"][0]["input"]="-1234.567";book["sheets"][0]["cells"][0]["style"]["numberFormat"]="$#,##0.00";WorkbookSession session(book);WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model,0,0,0,0);
 require(withDialog(model,view,[](QDialog* dialog){auto* category=dialog->findChild<QComboBox*>("formatCells.category");auto* decimals=dialog->findChild<QSpinBox*>("formatCells.decimalPlaces");auto* symbol=dialog->findChild<QComboBox*>("formatCells.currencySymbol");auto* negatives=dialog->findChild<QComboBox*>("formatCells.negativeStyle");auto* sample=dialog->findChild<QLabel*>("formatCells.sample");require(category&&symbol&&category->currentData()=="currency","existing Currency format initializes native currency options");require(decimals->value()==2&&symbol->currentData()=="$"&&negatives->currentData()=="minus","Currency options reflect actual cents, symbol and negative style");decimals->setValue(0);negatives->setCurrentIndex(negatives->findData("parentheses"));require(sample->text()=="($1,235)","Currency live sample rounds to whole dollars and uses negative parentheses");dialog->accept();}),"accept native Currency options");
 require(model.cellStyle(0,0).at("numberFormat")=="$#,##0;($#,##0)"&&model.data(model.index(0,0)).toString()=="($1,235)"&&model.raw(0,0)=="-1234.567","whole-dollar Currency format changes only display");const auto before=session.snapshot();
 require(!withDialog(model,view,[](QDialog* dialog){auto* category=dialog->findChild<QComboBox*>("formatCells.category");auto* decimals=dialog->findChild<QSpinBox*>("formatCells.decimalPlaces");auto* symbol=dialog->findChild<QComboBox*>("formatCells.currencySymbol");auto* negatives=dialog->findChild<QComboBox*>("formatCells.negativeStyle");auto* sample=dialog->findChild<QLabel*>("formatCells.sample");require(category->currentData()=="currency"&&decimals->value()==0&&negatives->currentData()=="parentheses","reopening Currency keeps whole-dollar and negative options");symbol->setCurrentIndex(symbol->findData(""));require(sample->text()=="(1,235)","None currency symbol is supported");symbol->setCurrentIndex(symbol->findData("€"));decimals->setValue(2);negatives->setCurrentIndex(negatives->findData("minus"));require(sample->text()=="-€1,234.57","currency symbol and cents update the sample");dialog->reject();})&&session.snapshot()==before,"cancelling native currency options discards the whole draft");
}
void nativeAccountingOptions(){
 auto book=fixture();book["sheets"][0]["cells"][0]["input"]="-1234.567";book["sheets"][0]["cells"][1]["input"]="0";WorkbookSession session(book);WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model,0,0,0,1);
 require(withDialog(model,view,[](QDialog* dialog){auto* category=dialog->findChild<QComboBox*>("formatCells.category");auto* decimals=dialog->findChild<QSpinBox*>("formatCells.decimalPlaces");auto* symbol=dialog->findChild<QComboBox*>("formatCells.currencySymbol");auto* negatives=dialog->findChild<QComboBox*>("formatCells.negativeStyle");auto* sample=dialog->findChild<QLabel*>("formatCells.sample");const int accounting=category->findData("accounting");require(accounting>=0,"Number tab offers Accounting with decimal and symbol options");category->setCurrentIndex(accounting);require(!negatives->isEnabled()&&negatives->currentData()=="parentheses"&&sample->text()=="($1,234.57)","Accounting uses standard fixed negative parentheses");decimals->setValue(0);symbol->setCurrentIndex(symbol->findData(""));require(sample->text()=="(1,235)","Accounting supports whole amounts and None symbol");dialog->accept();}),"accept native Accounting options");
 require(model.cellStyle(0,0).at("numberFormat")=="#,##0;(#,##0);-"&&model.data(model.index(0,0)).toString()=="(1,235)"&&model.data(model.index(0,1)).toString()=="-","Accounting formats negatives and zero using separate sections");const auto before=session.snapshot();require(withDialog(model,view,[](QDialog* dialog){require(dialog->findChild<QComboBox*>("formatCells.category")->currentData()=="accounting"&&dialog->findChild<QSpinBox*>("formatCells.decimalPlaces")->value()==0&&dialog->findChild<QComboBox*>("formatCells.currencySymbol")->currentData()=="","reopening Accounting reflects actual whole-number and None options");dialog->accept();})&&session.snapshot()==before,"unchanged Accounting acceptance preserves mixed styles and history");require(session.undo(),"Accounting formats the full selection in one undo");model.refresh();require(session.snapshotView().at("sheets")==book.at("sheets"),"Accounting undo restores numeric values and original formatting exactly");
}
void nativePercentageOptions(){
 auto book=fixture();book["sheets"][0]["cells"][0]["input"]="0.12567";book["sheets"][0]["cells"][0]["style"]["numberFormat"]="0%";WorkbookSession session(book);WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model,0,0,0,0);
 require(withDialog(model,view,[](QDialog* dialog){auto* category=dialog->findChild<QComboBox*>("formatCells.category");auto* decimals=dialog->findChild<QSpinBox*>("formatCells.decimalPlaces");auto* sample=dialog->findChild<QLabel*>("formatCells.sample");require(category->currentData()=="percentage"&&decimals->value()==0,"existing percentage initializes its actual decimal precision");require(decimals->isVisible()&&!dialog->findChild<QCheckBox*>("formatCells.thousandsSeparator")->isVisible()&&!dialog->findChild<QComboBox*>("formatCells.currencySymbol")->isVisible()&&!dialog->findChild<QComboBox*>("formatCells.negativeStyle")->isVisible(),"Percentage exposes relevant decimal options");decimals->setValue(3);require(sample->text()=="12.567%","Percentage sample scales only the rendered display");dialog->accept();}),"accept native Percentage precision");
 require(model.cellStyle(0,0).at("numberFormat")=="0.000%"&&model.data(model.index(0,0)).toString()=="12.567%"&&model.raw(0,0)=="0.12567","Percentage precision preserves the fractional stored value");require(session.undo(),"Percentage precision is one undo");model.refresh();require(session.snapshotView().at("sheets")==book.at("sheets"),"Percentage undo restores exact original formatting and value");
}
void nativeDateOptions(){
 WorkbookSession session;WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model,0,0,0,0);require(model.setData(model.index(0,0),"30/09/25",Qt::EditRole),"enter a date with day-first order and two-digit year");const auto before=session.snapshot();const auto raw=model.raw(0,0);
 require(withDialog(model,view,[](QDialog* dialog){auto* category=dialog->findChild<QComboBox*>("formatCells.category");auto* date=dialog->findChild<QComboBox*>("formatCells.dateFormat");auto* code=dialog->findChild<QComboBox*>("formatCells.numberFormat");auto* sample=dialog->findChild<QLabel*>("formatCells.sample");require(date&&category->currentData()=="date","entered date initializes native Date format choices");require(date->currentData()=="dd/mm/yy"&&code->currentText()=="dd/mm/yy"&&sample->text()=="30/09/25","Date defaults preserve the entered order, padding and year width");require(date->count()>=6&&!dialog->findChild<QSpinBox*>("formatCells.decimalPlaces")->isVisible(),"Date offers rendered types instead of irrelevant numeric decimal controls");date->setCurrentIndex(date->findData("yyyy-mm-dd"));require(sample->text()=="2025-09-30","Date sample previews the chosen rendering");dialog->accept();}),"accept native Date type");
 require(model.raw(0,0)==raw&&model.cellStyle(0,0).at("numberFormat")=="yyyy-mm-dd"&&model.data(model.index(0,0)).toString()=="2025-09-30","Date type changes display while preserving the stored date value");require(session.undo(),"Date display choices are one undo");model.refresh();require(session.snapshotView().at("sheets")==before.at("sheets"),"one undo restores the entered date format exactly");const auto restored=session.snapshot();require(withDialog(model,view,[](QDialog* dialog){require(dialog->findChild<QComboBox*>("formatCells.dateFormat")->currentData()=="dd/mm/yy","reopening Date restores the actual entered rendering");dialog->accept();})&&session.snapshot()==restored,"accepting unchanged Date options does not normalize the entered format");require(session.undo(),"undo the initial typed date after no-op acceptance");model.refresh();require(model.raw(0,0).isEmpty()&&!session.canUndo(),"unchanged Date acceptance adds no history");
}
void nativeGeneralTextCustomOptions(){
 auto book=fixture();book["sheets"][0]["cells"][0]["input"]="-1234.567";book["sheets"][0]["cells"][0]["style"]["numberFormat"]="#,##0.0;(#,##0.0)";WorkbookSession session(book);WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model,0,0,0,1);const auto before=session.snapshot();
 require(withDialog(model,view,[](QDialog* dialog){require(dialog->findChild<QComboBox*>("formatCells.category")->currentData()=="custom"&&dialog->findChild<QComboBox*>("formatCells.numberFormat")->currentText()=="#,##0.0;(#,##0.0)"&&dialog->findChild<QSpinBox*>("formatCells.decimalPlaces")->value()==1,"initial Custom override preserves the actual code and option values");dialog->accept();},{{"category","Custom"}})&&session.snapshot()==before&&!session.canUndo(),"accepting an initial Custom override preserves mixed styles and history");
 require(withDialog(model,view,[](QDialog* dialog){auto* category=dialog->findChild<QComboBox*>("formatCells.category");auto* code=dialog->findChild<QComboBox*>("formatCells.numberFormat");code->setEditText("0.0\" days\"");require(category->currentData()=="custom","editable custom literal units remain Custom instead of becoming Date");const int text=category->findData("text");require(text>=0,"native category selector includes Text");category->setCurrentIndex(text);require(code->currentText()=="@"&&!dialog->findChild<QSpinBox*>("formatCells.decimalPlaces")->isVisible(),"Text uses the standard Excel text format and hides numeric options");dialog->accept();}),"accept native Text category");
 require(model.cellStyle(0,0).at("numberFormat")=="@"&&model.cellStyle(0,1).at("numberFormat")=="@"&&model.raw(0,0)=="-1234.567"&&model.raw(0,1)=="=1+2"&&model.cellStyle(0,0).at("bold")==true&&model.cellStyle(0,1).at("italic")==true,"Text format preserves existing values, formulas and mixed font styles");
 require(withDialog(model,view,[](QDialog* dialog){auto* category=dialog->findChild<QComboBox*>("formatCells.category");require(category->currentData()=="text","existing Text initializes its actual category");category->setCurrentIndex(category->findData("general"));require(dialog->findChild<QComboBox*>("formatCells.numberFormat")->currentText()=="General","General resets the display format explicitly");dialog->accept();}),"accept native General category");require(model.cellStyle(0,0).at("numberFormat")=="General"&&model.data(model.index(0,0)).toString()=="-1234.567","General renders the existing unrounded value");
}
int main(int argc,char** argv){QApplication app(argc,argv);try{const auto test=argc>1?std::string(argv[1]):std::string();if(test=="number_options")nativeNumberOptions();else if(test=="currency_options")nativeCurrencyOptions();else if(test=="accounting_options")nativeAccountingOptions();else if(test=="percentage_options")nativePercentageOptions();else if(test=="date_options")nativeDateOptions();else if(test=="general_text_custom")nativeGeneralTextCustomOptions();else{directFormatting();clearFormats();nativeDialog();validation();noChanges();clearUnformatted();clearColors();explicitLeft();nativeNumberOptions();nativeCurrencyOptions();nativeAccountingOptions();nativePercentageOptions();nativeDateOptions();nativeGeneralTextCustomOptions();}std::cout<<"worksheet cell formatting tests passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
